update scenes s set width=r.width,height=r.height,asset_version=r.version::bigint,updated_at=now() from city_room_upgrade r where s.id=r.id;
update scenes set name='City Residences' where id='apartment-interior';
update buildings set display_name='City Residences' where id='building-apartment';
insert into spawn_points(id,scene_id,kind,x,y,facing)
select p.id,r.id,p.kind,p.x,p.y,'south' from city_room_upgrade r cross join lateral jsonb_to_recordset(r.spawns) as p(id text,kind text,x int,y int)
join scenes s on s.id=r.id
on conflict(id) do update set scene_id=excluded.scene_id,x=excluded.x,y=excluded.y,active=true;
update player_presence p set x=case when exists(select 1 from city_room_upgrade r cross join lateral jsonb_to_recordset(r.blocked) as b(x int,y int,width int,height int) where r.id=p.scene_id and p.x>=b.x and p.x<b.x+b.width and p.y>=b.y and p.y<b.y+b.height) then sp.x else p.x end,y=case when exists(select 1 from city_room_upgrade r cross join lateral jsonb_to_recordset(r.blocked) as b(x int,y int,width int,height int) where r.id=p.scene_id and p.x>=b.x and p.x<b.x+b.width and p.y>=b.y and p.y<b.y+b.height) then sp.y else p.y end,path='[]'::jsonb,path_index=0,scene_version=4,state_version=p.state_version+1 from spawn_points sp where sp.scene_id=p.scene_id and sp.kind='player_default';
update npc_runtime n set x=sp.x,y=sp.y,target_x=null,target_y=null,target_scene_id=null,target_spawn_id=null,last_simulated_at=null,state_version=n.state_version+1 from spawn_points sp where sp.scene_id=n.scene_id and sp.kind='player_default';
